def toolkit():
    icons=['<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7M10 7v6M7 10h6"/>','<rect x="2" y="2" width="7" height="7" rx="1"/><rect x="15" y="15" width="7" height="7" rx="1"/><path d="M9 5h9v10M5 9v9h10"/>','<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>','<path d="m14 2-9 12h7l-2 8 9-12h-7z"/>']
    cards=[('Discover','Research &<br>understanding','Turn questions into a clearer picture of people, their context, and the task they need to accomplish.','INTERVIEWS / PERSONAS / JOURNEY MAPPING'),('Structure','Flows &<br>prototypes','Give complex journeys a clear structure. Explore the path through wireframes and interactive prototypes.','USER FLOWS / WIREFRAMES / FIGMA'),('Design','Interfaces &<br>visual identities','Connect typography, color, and reusable components into an experience with purpose and character.','DESIGN SYSTEMS / UI / BRAND IDENTITY'),('Refine','Testing &<br>design delivery','Use feedback to refine the experience, review accessibility, and prepare clear designs for implementation.','USABILITY / ACCESSIBILITY / HANDOFF')]
    tags=[['Figma','Adobe XD','Sketch','Framer','Illustrator','Photoshop','InDesign'],['User research','Journey mapping','Wireframing','Prototyping','Interaction design'],['Design systems','Accessibility','Visual identity','Responsive design','Print production']]
    return '<section class="toolkit-section" id="toolkit"><div class="container"><div class="toolkit-heading reveal"><p class="section-label">04 / The toolkit</p><h2>Tools behind<br>the progress<span>.</span></h2><p>From understanding people to shaping the final experience.</p></div><div class="toolkit-tags">'+''.join('<div class="tag-row reveal">'+''.join('<span>'+x+'</span>' for x in row)+'</div>' for row in tags)+'</div><div class="toolkit-grid">'+''.join(f'<article class="toolkit-card reveal"><div class="toolkit-meta"><span>0{i+1} / {c[0]}</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">{icons[i]}</svg></div><h3>{c[1]}</h3><p>{c[2]}</p><div class="toolkit-foot">{c[3]}</div></article>' for i,c in enumerate(cards))+'</div></div></section>'

def career(arrow):
    roles=[('2024 — NOW','AbbVie','User Experience Designer','Healthcare products. Clearer workflows. Systems that scale.'),('2022 — 2024','Cotiviti','UI/UX Designer','Payment accuracy and analytics, translated into usable interfaces.'),('2021','Rogue Innovation + Design','UI/UX Designer Intern','Research, interactive prototypes, and high-fidelity design.'),('2016 — 2018','Way to Webs','UI/UX Designer','Responsive websites, e-commerce, and connected user journeys.'),('2015 — 2016','SABOO RKS Motors','Graphic Designer','The beginning: campaigns, print, and visual communication.')]
    return '<section class="career-section" id="experience"><div class="career-ghost" aria-hidden="true">EXPERIENCE</div><div class="container"><div class="section-title"><div><p class="section-label">02 / The journey so far</p><h2>Good design.<br>Built on experience.</h2></div><div class="career-controls"><button class="career-prev" aria-label="Previous experience">←</button><button class="career-next" aria-label="Next experience">→</button></div></div><div class="career-track" tabindex="0" role="region" aria-label="Professional experience; use arrow keys to explore">'+''.join(f'<article class="career-card"><div class="career-meta"><span>{r[0]}</span><span>0{i+1}</span></div><h3>{r[1]}</h3><p class="career-role">{r[2]}</p><p>{r[3]}</p></article>' for i,r in enumerate(roles))+f'</div><div class="career-bottom"><span>From visual communication to complex digital products.</span><a class="text-link" href="/resume/">Full experience {arrow()}</a></div></div></section>'

